"use client";

import { useEffect, useState } from "react";
import { IDataPersonalHome } from "@/dto/data-personalHome-DTO";
import { BaseUrlFoto } from "@/utils/base-url-foto";
import { useForm } from "react-hook-form";
import { AlunoSchemaDTO, schemaAluno } from "@/schemas/schema-aluno";
import { zodResolver } from "@hookform/resolvers/zod";

type props = {
  personal: IDataPersonalHome | any;
};

export function PerfilSection({ personal }: props) {
  if (!personal) return

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset, } = useForm<AlunoSchemaDTO>({ resolver: zodResolver(schemaAluno) })

  const photo = BaseUrlFoto(personal.foto);
  const [frontFoto, setFrontFoto] = useState(photo);

  useEffect(() => {
    if (personal) {
      reset({
        nome: personal.nome,
        sobrenome: personal.sobrenome,
        email: personal.email,
        telefone: personal.telefone,
        formacao: personal.formacao
      })

      if (typeof personal.foto === 'string') {
        setFrontFoto(photo)
      }
    }
  }, [personal, reset, open])
  function FilePicker(e: any) {
    let file: File = e.target.files[0];
    if (!file) return;

    let foto = URL.createObjectURL(file);

    setFrontFoto(foto);
  }

  return (
    <div className="w-full h-full flex flex-col  overflow-x-hidden ">
      <form
        onSubmit={handleSubmit()}
        className="w-full h-full flex flex-col gap-8 overflow-y-scroll  text-xl p-8 px-12 text-neutras-100"
      >
        <h1 className="font-Poppins-Bold">Meu perfil</h1>

        <div className="w-full max-md:h-fit max-md:flex-col p-4 h-36 bg-white shadow-2xl flex flex-row gap-4 shadow-neutras-100/10  rounded-2xl border-2 border-neutras-100/10">
          <div
            className="h-full aspect-square rounded-full bg-neutras-200/20"
            style={{
              backgroundImage: `url(${frontFoto})`,
              backgroundSize: "cover",
              backgroundPosition: "center"
            }}
          >
            {" "}
            <input
              onChange={(e) => FilePicker(e)}
              className="w-full cursor-pointer rounded-full h-full opacity-0"
              type="file"
            />
          </div>
          <div className="h-30 full flex flex-col justify-center items-start text-xl max-md:items-center  text-verde-200">
            <h1 className="text-xl font-Poppins-Semibold text-black">
              {personal?.nome} {personal?.sobrenome}
            </h1>
            <h1 className="text-sm font-Poppins mb-4">personal</h1>

            <h1 className="text-sm font-Poppins w-full"> {personal.telefone || "sem telefone"}</h1>
            <h1 className="text-sm font-Poppins w-full">{personal?.email || "sem email"}</h1>
          </div>
        </div>

        <h1 className="font-Poppins-Bold">Informações Pessoais</h1>

        <div className="w-full p-4 bg-white shadow-2xl text-neutras-200 flex flex-col gap-4 shadow-neutras-100/10  rounded-2xl border-2 border-neutras-100/10">
          <div className="w-full">
            <label
            htmlFor="email"
            className="w-full wrap-normal whitespace-nowrap border-2 h-10 rounded-lg col-span-2 text-base flex flex-row font-Poppins-Medium p-2 border-neutras-200/20"
          >
            Email: 
            <input
              {...register("email")}
              type="text"
              name="email"
              className="w-full px-2 flex items-end h-full text-base outline-0"
            />
          </label>
          </div>

          <div className="h-full w-full grid grid-cols-2 place-items-center">
            <div className="w-1/2">
            <label
            htmlFor="email"
            className="w-full wrap-normal whitespace-nowrap border-2 h-10 rounded-lg col-span-2 text-base flex flex-row font-Poppins-Medium p-2 border-neutras-200/20"
          >
            Email: 
            <input
              {...register("email")}
              type="text"
              name="email"
              className="w-full px-2 flex items-end h-full text-base outline-0"
            />
          </label>
          </div>
          </div>
        </div>
      </form>
    </div>
  );
}
